starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "ami_id" {
  description = "Input variable ami_id."
  type        = string
}

variable "instance_type" {
  description = "Input variable instance_type."
  type        = string
  default     = "t2.micro"
}

variable "subnet_id" {
  description = "Input variable subnet_id."
  type        = string
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_instance" "this" {
  # TODO - Complete the aws_instance resource.
  # Add the arguments and nested blocks required for aws_instance.
}
